package com.triptales.app;
import android.os.*;import android.view.*;import android.widget.*;import androidx.fragment.app.Fragment;import org.json.*;import java.io.*;import java.net.*;
public class WeatherFragment extends Fragment{
 EditText city;TextView result;
 public View onCreateView(LayoutInflater i,ViewGroup c,Bundle b){View v=i.inflate(R.layout.fragment_weather,c,false);city=v.findViewById(R.id.cityEdit);result=v.findViewById(R.id.weatherResult);v.findViewById(R.id.weatherButton).setOnClickListener(x->load());return v;}
 void load(){String q=city.getText().toString().trim();if(q.isEmpty()){result.setText("Enter a city.");return;}result.setText("Loading weather...");new Thread(()->{try{String enc=URLEncoder.encode(q,"UTF-8");URL geo=new URL("https://geocoding-api.open-meteo.com/v1/search?name="+enc+"&count=1&language=en&format=json");JSONObject gj=new JSONObject(read(geo.openStream()));JSONArray a=gj.optJSONArray("results");if(a==null||a.length()==0)throw new Exception("City not found");JSONObject loc=a.getJSONObject(0);double lat=loc.getDouble("latitude"),lon=loc.getDouble("longitude");URL w=new URL("https://api.open-meteo.com/v1/forecast?latitude="+lat+"&longitude="+lon+"&current=temperature_2m,relative_humidity_2m,wind_speed_10m,weather_code");JSONObject j=new JSONObject(read(w.openStream())).getJSONObject("current");String out="📍 "+loc.optString("name")+"\n\nTemperature: "+j.optDouble("temperature_2m")+" °C\nHumidity: "+j.optInt("relative_humidity_2m")+"%\nWind: "+j.optDouble("wind_speed_10m")+" km/h\nWeather code: "+j.optInt("weather_code")+"\n\nSource: Open-Meteo REST API";requireActivity().runOnUiThread(()->result.setText(out));}catch(Exception e){requireActivity().runOnUiThread(()->result.setText("Weather error: "+e.getMessage()));}}).start();}
 String read(InputStream in)throws Exception{BufferedReader b=new BufferedReader(new InputStreamReader(in));StringBuilder s=new StringBuilder();String l;while((l=b.readLine())!=null)s.append(l);b.close();return s.toString();}
}
